// Dial starts at 2; reaching 4 makes the room cold, reaching 3 makes it warm, and if it never reaches 3 the room is warm only after the last action was "turn up".
function visible(actions) {
  let dial = 2;
  let maxDial = 2;
  let lastAction = "";

  for (const action of actions) {
    if (action === "turn up") {
      dial = Math.min(dial + 1, 4);
    } else if (action === "turn down") {
      dial = Math.max(dial - 1, 0);
    }
    // "wait" leaves the dial unchanged
    maxDial = Math.max(maxDial, dial);
    lastAction = action;
  }

  if (maxDial >= 4) {
    return { room: "cold" };
  }
  if (maxDial === 3) {
    return { room: "warm" };
  }
  return { room: lastAction === "turn up" ? "warm" : "cold" };
}

